/**
 * Unit tests for EmbeddedRungeKuttaIntegrator.integrate
 */
public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen1Test {

    private TestIntegrator integrator;
    private FirstOrderDifferentialEquations equations;

    // Concrete implementation for testing protected/abstract methods
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
        private double errorToReturn = 0.0;
        private boolean managerResetReturn = false;
        private boolean managerStopReturn = false;
        private boolean eventTriggered = false;

        protected TestIntegrator() {
            super("TestIntegrator", true, 
                  new double[]{0.5, 1.0}, 
                  new double[][]{{0.0, 0.0}, {0.5, 0.0}}, 
                  new double[]{0.0, 1.0}, 
                  null, 1e-10, 1e10, 1e-6, 1e-6);
        }

        @Override
        public int getOrder() { return 2; }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            return errorToReturn;
        }

        // Mocking behavior for internal dependencies via overrides or spy logic if necessary
        // Since we can't easily mock the internal 'manager' or 'interpolator' due to local instantiation,
        // we rely on the mathematical flow or a Spy.
    }

    @Before
    public void setUp() {
        integrator = spy(new TestIntegrator());
        equations = new FirstOrderDifferentialEquations() {
            @Override
            public int getDimension() { return 1; }
            @Override
            public void computeDerivatives(double t, double[] y, double[] yDot) {
                yDot[0] = y[0]; // dy/dt = y -> y(t) = e^t
            }
        };
    }

    @Test
    public void testIntegrate_SimpleForward() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t = 1.0;
        double[] y = new double[1];

        // Default error 0.0 means step is accepted immediately
        doReturn(0.0).when(integrator).estimateError(any(), any(), any(), anyDouble());

        double stopTime = integrator.integrate(equations, t0, y0, t, y);

        assertEquals(t, stopTime, 1e-6);
        assertTrue(y[0] > 1.0);
    }

    @Test
    public void testIntegrate_Backward() throws Exception {
        double t0 = 1.0;
        double[] y0 = {Math.E};
        double t = 0.0;
        double[] y = new double[1];

        double stopTime = integrator.integrate(equations, t0, y0, t, y);

        assertEquals(t, stopTime, 1e-6);
        assertEquals(1.0, y[0], 1e-6);
    }

    @Test
    public void testIntegrate_StepRejection() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t = 1.0;
        double[] y = new double[1];

        // Force error > 1.0 to trigger rejection and step size reduction
        doReturn(2.0).when(integrator).estimateError(any(), any(), any(), anyDouble());
        // After one rejection, return 0 to allow progress
        doReturn(0.0).doReturn(0.0).when(integrator).estimateError(any(), any(), any(), anyDouble());

        integrator.integrate(equations, t0, y0, t, y);
        verify(integrator, atLeastOnce()).estimateError(any(), any(), any(), anyDouble());
    }

    @Test
    public void testIntegrate_WithStepHandlers() throws Exception {
        StepHandler handler = mock(StepHandler.class);
        integrator.addStepHandler(handler);

        double t0 = 0.0;
        double[] y0 = {1.0};
        double t = 0.5;
        double[] y = new double[1];

        integrator.integrate(equations, t0, y0, t, y);
        verify(handler, atLeastOnce()).handleStep(any(), anyBoolean());
    }

