    public void testIntegrate_ZeroStepSizeEvent() throws Exception {
        // This tests the branch: if (Math.abs(dt) <= Math.ulp(stepStart))
        // This requires mocking the manager to return a very small dt.
        // Due to the complexity of the internal 'manager' instantiation, 
